// designElectronics — translations. See i18n.h for the model.
#include "i18n.h"

#include <SDL3/SDL.h>

#include <algorithm>
#include <cctype>
#include <cstdio>
#include <map>
#include <mutex>
#include <set>
#include <vector>

#include "json.h"

// Generated by cmake/embed_parts.cmake from i18n/*.json.
extern "C" const unsigned char de_i18n[];
extern "C" const unsigned long de_i18n_size;

namespace {

// std::less<> gives heterogeneous lookup: tr("menu.file.new") with a const char*
// allocates nothing. References into a std::map are stable forever, which is what
// lets tr() return const std::string&.
using Table = std::map<std::string, std::string, std::less<>>;

std::map<std::string, Table> g_tables;  // language code -> key -> text (never erased)
std::vector<LangInfo> g_langs;          // menu order: English first, then codes
const Table* g_active = nullptr;
const Table* g_english = nullptr;
std::string g_lang = "en";
bool g_loaded = false;

// Keys that no pack provides. Memoised so the returned reference stays valid for
// the lifetime of the process; guarded because worker threads (uploads, the AI
// bridge) can format status text too.
Table g_miss;
std::mutex g_missMutex;
std::vector<std::string> g_missingList;

const std::string* findRaw(const std::string& key) {
    if (g_active) {
        auto it = g_active->find(key);
        if (it != g_active->end()) return &it->second;
    }
    if (g_english) {
        auto it = g_english->find(key);
        if (it != g_english->end()) return &it->second;
    }
    return nullptr;
}

const std::string& miss(const std::string& key) {
    std::lock_guard<std::mutex> lock(g_missMutex);
    auto it = g_miss.find(key);
    if (it == g_miss.end()) {
        it = g_miss.emplace(key, key).first;
        g_missingList.push_back(key);
        SDL_Log("i18n: no translation for \"%s\"", key.c_str());
    }
    return it->second;
}

std::string lowerAscii(std::string s) {
    for (auto& c : s) c = (char)std::tolower((unsigned char)c);
    return s;
}

std::string trim(const std::string& s) {
    size_t a = 0, b = s.size();
    while (a < b && (unsigned char)s[a] <= ' ') a++;
    while (b > a && (unsigned char)s[b - 1] <= ' ') b--;
    return s.substr(a, b - a);
}

std::string langPart(const std::string& code) {
    size_t dash = code.find_first_of("-_");
    return lowerAscii(dash == std::string::npos ? code : code.substr(0, dash));
}

void ensureLang(const std::string& code, const std::string& nativeName, const std::string& englishName, bool rtl) {
    for (auto& l : g_langs) {
        if (l.code != code) continue;
        if (!nativeName.empty()) l.nativeName = nativeName;
        if (!englishName.empty()) l.englishName = englishName;
        l.rtl = rtl;
        return;
    }
    g_langs.push_back({code, nativeName.empty() ? code : nativeName, englishName.empty() ? code : englishName, rtl});
}

// A pack is a flat JSON object; "_meta" describes it.
bool loadPack(const std::string& fileName, const std::string& text) {
    std::string err;
    Json j = Json::parse(trim(text), &err);
    if (!j.isObject()) {
        SDL_Log("i18n: %s is not a JSON object (%s)", fileName.c_str(), err.c_str());
        return false;
    }
    const Json& meta = j["_meta"];
    std::string code = meta["code"].str();
    if (code.empty()) {
        code = fileName;
        size_t dot = code.find_last_of('.');
        if (dot != std::string::npos) code.resize(dot);
    }
    ensureLang(code, meta["native"].str(), meta["name"].str(), meta["rtl"].boolean(false));
    Table& table = g_tables[code];
    size_t n = 0;
    for (auto& kv : j.members()) {
        if (kv.first == "_meta") continue;
        table[kv.first] = kv.second.str();
        n++;
    }
    SDL_Log("i18n: loaded %s (%s, %zu strings)", code.c_str(), fileName.c_str(), n);
    return true;
}

// The blob is "@file name.json\n<contents>\n" repeated, in file-name order.
void loadBlob(const std::string& blob) {
    size_t pos = 0;
    while (pos < blob.size()) {
        size_t at = blob.find("@file ", pos);
        while (at != std::string::npos && at > 0 && blob[at - 1] != '\n') at = blob.find("@file ", at + 1);
        if (at == std::string::npos) break;
        size_t lineEnd = blob.find('\n', at);
        if (lineEnd == std::string::npos) break;
        std::string name = trim(blob.substr(at + 6, lineEnd - at - 6));
        size_t nextAt = blob.find("@file ", lineEnd);
        while (nextAt != std::string::npos && nextAt > 0 && blob[nextAt - 1] != '\n') nextAt = blob.find("@file ", nextAt + 1);
        size_t bodyEnd = nextAt == std::string::npos ? blob.size() : nextAt;
        loadPack(name, blob.substr(lineEnd + 1, bodyEnd - lineEnd - 1));
        pos = bodyEnd;
    }
}

// Packs next to the executable (or in the preferences folder) override the
// built-in ones key by key; unknown codes add a language.
void loadOverrideDir(const std::string& dir) {
    if (dir.empty()) return;
    struct Ctx {
        std::string dir;
        std::vector<std::string> files;
    } ctx;
    ctx.dir = dir;
    SDL_EnumerateDirectory(
        dir.c_str(),
        [](void* userdata, const char* dirname, const char* fname) -> SDL_EnumerationResult {
            auto* c = (Ctx*)userdata;
            std::string name = fname;
            if (name.size() > 5 && name.compare(name.size() - 5, 5, ".json") == 0) c->files.push_back(name);
            return SDL_ENUM_CONTINUE;
        },
        &ctx);
    if (ctx.files.empty()) return;
    std::sort(ctx.files.begin(), ctx.files.end());
    for (auto& f : ctx.files) {
        std::string path = ctx.dir;
        if (!path.empty() && path.back() != '/' && path.back() != '\\') path += '/';
        path += f;
        size_t size = 0;
        void* data = SDL_LoadFile(path.c_str(), &size);
        if (!data) continue;
        std::string text((const char*)data, size);
        SDL_free(data);
        loadPack(f, text);
    }
}

std::string withSlash(std::string p) {
    if (!p.empty() && p.back() != '/' && p.back() != '\\') return p + '/';
    return p;
}

void rebuildLanguageList() {
    // English first (it is the source language), then alphabetical.
    std::sort(g_langs.begin(), g_langs.end(), [](const LangInfo& a, const LangInfo& b) {
        if ((a.code == "en") != (b.code == "en")) return a.code == "en";
        return a.code < b.code;
    });
}

std::string subst(const std::string& pattern, const std::vector<std::string>& args) {
    std::string out;
    out.reserve(pattern.size() + 16);
    for (size_t i = 0; i < pattern.size();) {
        char c = pattern[i];
        if (c == '{' && i + 1 < pattern.size() && pattern[i + 1] == '{') { out += '{'; i += 2; continue; }
        if (c == '}' && i + 1 < pattern.size() && pattern[i + 1] == '}') { out += '}'; i += 2; continue; }
        if (c == '{') {
            size_t close = pattern.find('}', i + 1);
            if (close != std::string::npos && close > i + 1 && close - i - 1 <= 3) {
                size_t idx = 0;
                bool digits = true;
                for (size_t k = i + 1; k < close; k++) {
                    if (pattern[k] < '0' || pattern[k] > '9') { digits = false; break; }
                    idx = idx * 10 + (size_t)(pattern[k] - '0');
                }
                if (digits) {
                    if (idx < args.size()) out += args[idx];
                    i = close + 1;
                    continue;
                }
            }
        }
        out += c;
        ++i;
    }
    return out;
}

}  // namespace

// ---------------------------------------------------------------------------

const std::string& tr(const char* key) {
    if (!key) return miss(std::string());
    if (const std::string* s = findRaw(key)) return *s;
    return miss(std::string(key));
}

const std::string& tr(const std::string& key) {
    if (const std::string* s = findRaw(key)) return *s;
    return miss(key);
}

std::string trf(const char* key, std::initializer_list<std::string> args) {
    return subst(tr(key), std::vector<std::string>(args));
}

std::string trn(const char* key, long long n) {
    std::string base(key ? key : "");
    const std::string* pattern = nullptr;
    if (n == 1) pattern = findRaw(base + ".one");
    if (!pattern) pattern = findRaw(base + ".other");
    if (!pattern) pattern = findRaw(base + ".one");
    if (!pattern) return tr(base);
    return subst(*pattern, {std::to_string(n)});
}

std::string num(double v, int decimals) {
    char b[64];
    if (decimals < 0) decimals = 0;
    if (decimals > 9) decimals = 9;
    std::snprintf(b, sizeof b, "%.*f", decimals, v);
    return b;
}

std::string slugify(const std::string& english) {
    std::string out;
    for (unsigned char c : english) {
        if (std::isalnum(c)) {
            out += (char)std::tolower(c);
        } else if (!out.empty() && out.back() != '_') {
            out += '_';
        }
    }
    while (!out.empty() && out.back() == '_') out.pop_back();
    return out;
}

std::string viewLabel(int v) {
    return tr(v == 0 ? "view.breadboard" : v == 1 ? "view.schematic" : "view.pcb");
}

// ---------------------------------------------------------------------------
// i18n namespace
// ---------------------------------------------------------------------------

namespace i18n {

void initEmbedded() {
    if (g_loaded) return;
    g_loaded = true;
    if (de_i18n_size) loadBlob(std::string((const char*)de_i18n, (size_t)de_i18n_size));
    auto en = g_tables.find("en");
    if (en == g_tables.end()) {
        // A build with no packs at all: keep the tables empty so tr() reports keys.
        ensureLang("en", "English", "English", false);
        en = g_tables.emplace("en", Table()).first;
    }
    g_english = &en->second;
    g_active = g_english;
    g_lang = "en";
    rebuildLanguageList();
}

void init(const std::string& force) {
    initEmbedded();

    const char* base = SDL_GetBasePath();
    std::string b = base ? withSlash(base) : std::string();
    if (!b.empty()) {
        loadOverrideDir(b + "i18n");
        loadOverrideDir(b + "../Resources/i18n");  // macOS bundle
    }
    char* pref = SDL_GetPrefPath("designElectronics", "designElectronics");
    if (pref) {
        loadOverrideDir(withSlash(pref) + "i18n");
        SDL_free(pref);
    }
    rebuildLanguageList();

    std::string want = force;
    if (want.empty()) want = systemLanguage();
    if (!setLang(want)) setLang("en");
}

const std::vector<LangInfo>& languages() { return g_langs; }

const std::string& lang() { return g_lang; }

bool setLang(const std::string& code) {
    auto it = g_tables.find(code);
    if (it == g_tables.end() || code.empty()) return false;
    g_active = &it->second;
    g_lang = it->first;
    return true;
}

std::string systemLanguage() {
    int count = 0;
    SDL_Locale** locales = SDL_GetPreferredLocales(&count);
    std::string best;
    if (locales) {
        for (int i = 0; i < count && best.empty(); i++) {
            const SDL_Locale* l = locales[i];
            if (!l || !l->language) continue;
            std::string language = lowerAscii(l->language);
            std::string full = language;
            if (l->country && *l->country) full += "-" + lowerAscii(l->country);
            // exact code first ("zh-cn"), then any pack for that language ("zh")
            for (auto& info : g_langs)
                if (lowerAscii(info.code) == full) { best = info.code; break; }
            if (best.empty())
                for (auto& info : g_langs)
                    if (langPart(info.code) == language) { best = info.code; break; }
        }
        SDL_free(locales);
    }
    if (best.empty() || !g_tables.count(best)) best = "en";
    return best;
}

const std::vector<std::string>& missing() {
    std::lock_guard<std::mutex> lock(g_missMutex);
    return g_missingList;
}

bool exists(const char* key) { return key && findRaw(key) != nullptr; }

std::vector<std::string> packCodes() {
    std::vector<std::string> codes;
    for (auto& kv : g_tables) codes.push_back(kv.first);
    return codes;
}

std::string dumpPack(const std::string& code) {
    auto it = g_tables.find(code);
    if (it == g_tables.end()) return std::string();
    Json j = Json::object();
    for (auto& l : g_langs) {
        if (l.code != code) continue;
        Json meta = Json::object();
        meta.set("code", Json(code));
        meta.set("native", Json(l.nativeName));
        meta.set("name", Json(l.englishName));
        meta.set("version", Json(1));
        j.set("_meta", meta);
        break;
    }
    for (auto& kv : it->second) j.set(kv.first, Json(kv.second));
    return j.dump(2);
}

}  // namespace i18n
